import dspy
from dspy.teleprompt import BootstrapFewShotWithRandomSearch
from dspy.utils.dummies import DummyLM


class SimpleModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predictor = dspy.Predict("question -> answer")

    def forward(self, question):
        return self.predictor(question=question)



def metric(example, prediction, trace=None):
    return example.answer == prediction.answer


dspy.configure(
    lm=DummyLM(
        {
            "q1": {"answer": "A"},
            "q2": {"answer": "B"},
        }
    )
)

trainset = [
    dspy.Example(question="q1", answer="A").with_inputs("question"),
    dspy.Example(question="q2", answer="B").with_inputs("question"),
]

optimizer = BootstrapFewShotWithRandomSearch(
    metric=metric,
    num_candidate_programs=1,
    max_bootstrapped_demos=1,
    max_labeled_demos=1,
    num_threads=1,
)
best = optimizer.compile(SimpleModule(), teacher=SimpleModule(), trainset=trainset, valset=trainset)
seeds = [candidate["seed"] for candidate in best.candidate_programs]
print(len(seeds), seeds)
assert len(seeds) == 4
assert set(seeds) == {-3, -2, -1, 0}
